messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>3D Humanoid Treadmill Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x888888);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 1.6, 4);
camera.lookAt(0, 1, 0);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Ground (treadmill surface)
const groundGeometry = new THREE.PlaneGeometry(20, 4);
const groundMaterial = new THREE.MeshPhongMaterial({ color: 0x777777, side: THREE.DoubleSide });
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Humanoid model (low-poly)
function createHumanoid() {
    const body = new THREE.CylinderGeometry(0.25, 0.25, 1, 8);
    const torso = new THREE.Mesh(body, new THREE.MeshPhongMaterial({ color: 0x4444aa }));
    torso.position.set(0, 0.5, 0);

    const head = new THREE.SphereGeometry(0.25, 16, 16);
    const headMesh = new THREE.Mesh(head, new THREE.MeshPhongMaterial({ color: 0x4444aa }));
    headMesh.position.set(0, 1.25, 0);
    torso.add(headMesh);

    // Arms
    const armGeometry = new THREE.CylinderGeometry(0.08, 0.08, 0.7, 8);
    const leftArm = new THREE.Mesh(armGeometry, new THREE.MeshPhongMaterial({ color: 0x4444aa }));
    leftArm.rotation.x = Math.PI / 2;
    leftArm.position.set(-0.5, 0.75, 0);
    torso.add(leftArm);

    const rightArm = armGeometry.clone();
    rightArm.position.set(0.5, 0.75, 0);
    torso.add(rightArm);

    // Legs
    const legGeometry = new THREE.CylinderGeometry(0.15, 0.15, 1, 8);
    const leftLeg = new THREE.Mesh(legGeometry, new THREE.MeshPhongMaterial({ color: 0x4444aa }));
    leftLeg.position.set(-0.25, 0.5, 0.5);
    leftLeg.rotation.z = Math.PI / 2;
    torso.add(leftLeg);

    const rightLeg = legGeometry.clone();
    rightLeg.position.set(0.25, 0.5, -0.5);
    rightLeg.rotation.z = -Math.PI / 2;
    torso.add(rightLeg);

    return torso;
}
const humanoid = createHumanoid();
scene.add(humanoid);

// Animation controls
let state = 'stand'; // 'stand', 'walk', 'run'
let phase = 0; // 0-100 progress in current state
let walkSpeed = 0; // Target limb swing angle (radians)
let runSpeed = 0;
let leanAngle = 0; // Forward lean for running

// Limb swing parameters
const walkSwing = 0.2; // Max angle for walking limbs
const runSwing = 0.6;  // Max angle for running limbs
const walkFrequency = 0.02; // Degrees per frame (slow)
const runFrequency = 0.05;  // Degrees per frame (fast)

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // State machine
    if (state === 'stand') {
        phase += 0.05;
        if (phase >= 100) {
            phase = 0;
            state = 'walk';
        }
    } else if (state === 'walk') {
        phase += walkFrequency;
        walkSwing = Math.sin(phase * Math.PI / 50) * walkSwing; // Sinusoidal swing
        if (phase >= 100) {
            phase = 0;
            state = 'run';
        }
    } else if (state === 'run') {
        phase += runFrequency;
        runSwing = Math.sin(phase * Math.PI / 25) * runSwing; // Faster swing
        leanAngle = Math.sin(phase * Math.PI / 12) * 0.1; // Slight forward lean
        if (phase >= 100) {
            phase = 0;
            state = 'stand';
        }
    }

    // Apply limb movements based on state
    humanoid.traverse(child => {
        if (child.isMesh && (child.name === 'leftArm' || child.name === 'rightArm' || child.name === 'leftLeg' || child.name === 'rightLeg')) {
            if (state === 'walk') {
                const swing = walkSwing * (child.name.includes('left') ? 1 : -1);
                child.rotation.z = swing;
            } else if (state === 'run') {
                const swing = runSwing * (child.name.includes('left') ? 1 : -1);
                child.rotation.z = swing;
            }
        }
    });

    // Apply forward lean for running
    humanoid.rotation.y = leanAngle;

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation immediately
animate();
</script>
</body>
</html>
```
